"""Build an offline picker, label editor and native ligand/receptor contact preview."""
from pathlib import Path
import json
f=Path(__file__).resolve().parent
icons=json.loads((f/'manifest.json').read_text())
for e in icons:e['svg']=(f/Path(e['file']).name).read_text()
models=[]
for receptor,ligand,scale in [('y','triangle',.6),('cup','circle',.7)]:
 models.append({'id':receptor,'layout':{'width':400,'height':250,'pitch':100,'zones':{'receptor':135,'ligand':35}},'entities':[{'id':'receptor','icon':'generic-receptor-'+receptor,'slot':1,'zone':'receptor','scale':1},{'id':'ligand','icon':'generic-ligand-'+ligand,'slot':1,'zone':'ligand','scale':scale}],'events':[{'id':'bind','kind':'dock','actor':'ligand','port':'receptor','target':'receptor','targetPort':'ligand','duration':2}]})
(f/'assembly-models.json').write_text(json.dumps(models,indent=2)+'\n')
engine=(f.parents[2]/'scripts/domain-motion.js').read_text()
page='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Generic 图标 · 蛋白、配体、受体与 RNA</title><style>
*{box-sizing:border-box}[hidden]{display:none!important}body{margin:0;background:#f6f9f7;color:#28474b;font:15px/1.7 Arial,sans-serif}main{max-width:1200px;margin:auto;padding:30px 24px}h1{font-size:32px;line-height:1.3}h2{font-size:23px}h3{font-size:17px;margin:8px 0}p{max-width:850px}a{color:#276d73}button,input,select{font:inherit;color:inherit}button,select,input[type=text]{background:white;border:1px solid #b9ceca;border-radius:5px;padding:7px 12px}button{cursor:pointer}button[aria-pressed=true]{background:#dbece6}.toolbar{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:20px 0}.editor{display:grid;grid-template-columns:1fr 1fr;gap:28px;margin:24px 0 40px;padding:24px;background:white;border:1px solid #d2dfda;border-radius:9px}.controls{display:grid;gap:14px}.controls label{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.controls label>span{width:90px}.controls select,.controls input[type=text]{width:min(260px,100%)}.stage{display:grid;place-items:center;background:#f6f9f7;border-radius:7px;min-height:280px}.stage svg{width:240px;height:288px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.card{padding:17px;background:white;border:1px solid #d2dfda;border-radius:8px;min-width:0}.art{height:170px;display:flex;align-items:center;justify-content:center}.art img{width:160px;height:160px}.card p,.note{font-size:14px}.links{display:flex;gap:12px;flex-wrap:wrap;font-size:14px}.links button{padding:1px 8px;font-size:14px}.assembly{display:grid;grid-template-columns:1fr 1fr;gap:16px}.assembly svg{display:block;width:100%;height:260px;background:#f6f9f7}.tag{font-size:13px;letter-spacing:1px;color:#597978}input[type=range]{max-width:100%}footer{margin:30px 0;font-size:14px}@media(max-width:800px){.grid{grid-template-columns:1fr 1fr}.editor{grid-template-columns:1fr}.assembly{grid-template-columns:1fr}h1{font-size:27px}}@media(max-width:460px){main{padding:20px 14px}.grid{grid-template-columns:1fr}.editor{padding:17px}.stage svg{width:200px;height:240px}.controls select{width:100%}}
</style></head><body><main><a href="../../../../../icons.html">← 当前图标库</a><p class="tag">GENERIC PRIMITIVES · 18 NATIVE SVGs</p><h1>简单形状，也能讲清机制。</h1><p>圆角矩形表示蛋白，分叉或杯形表示受体，梯子表示配对的核酸。选择图标后可改色、添加名称并下载；圆角矩形和胶囊形蛋白还可调整长宽。</p><section class="editor" aria-label="图标编辑器"><div class="controls"><h2>选一个，直接使用。</h2><label><span>图标</span><select id="pick" aria-label="选择图标"></select></label><label><span>名称</span><input id="name" aria-label="图标名称" type="text" maxlength="12" value="Protein A"></label><label><span>主色</span><select id="color" aria-label="图标主色"><option value="#69ADB5">蓝绿色</option><option value="#B2A6CD">柔紫色</option><option value="#E4BE78">沙金色</option><option value="#B3D7CC">薄荷色</option><option value="#D98E83">珊瑚色</option></select></label><label><span>蛋白宽度</span><input id="width" aria-label="蛋白宽度" type="range" min="72" max="136" value="120"></label><label><span>蛋白高度</span><input id="height" aria-label="蛋白高度" type="range" min="36" max="88" value="52"></label><div class="toolbar"><button id="export">下载当前 SVG ↓</button><button id="reset">恢复原图</button></div><p id="hint" class="note"></p></div><div class="stage" id="stage"></div></section>
<h2>18 个通用图标</h2><div class="toolbar"><label>查看尺寸 <select id="size" aria-label="查看尺寸"><option>64</option><option>96</option><option selected>160</option></select> px</label><label>类别 <select id="category" aria-label="筛选类别"><option value="all">全部</option><option value="proteins">蛋白</option><option value="ligands">配体</option><option value="receptors">受体</option><option value="nucleic-acids">RNA</option><option value="compartments">膜与囊泡</option></select></label></div><div id="icons" class="grid"></div>
<h2>配体–受体组合</h2><p>三角配体配 Y 型受体，圆形配体配杯形受体。拖动滑块比较游离与结合。膜片段作为背景单独放置，方便调整细胞外与胞内部分。</p><div class="toolbar"><label for="progress">结合进度</label><input id="progress" type="range" min="0" max="2" step=".01" value="2"><button id="play">播放</button></div><div class="assembly"><article class="card"><h3>Y 型受体 + 三角配体</h3><svg id="pair-0" viewBox="0 0 400 250" role="img" aria-label="Y 型受体结合示意"></svg></article><article class="card"><h3>杯形受体 + 圆形配体</h3><svg id="pair-1" viewBox="0 0 400 250" role="img" aria-label="杯形受体结合示意"></svg></article></div><p class="note">这些形状是通路图的符号。双链梯子、单侧梯齿和发夹表示不同的 RNA 拓扑；5′/3′ 方向与具体序列由组图中的独立标记补充。</p><footer><a href="manifest.json">部件、锚点与参考</a> · <a href="../../../../../downloads/current-examples.zip">下载当前全部示例</a> · <a href="build.py">图标源代码</a></footer></main><script>/*ENGINE*/</script><script>
const ICONS=/*ICONS*/,MODELS=/*MODELS*/,NS='http://www.w3.org/2000/svg';const $=s=>document.querySelector(s),byId=Object.fromEntries(ICONS.map(e=>[e.id,e]));
const uri=s=>'data:image/svg+xml;base64,'+btoa(unescape(encodeURIComponent(s)));
$('#pick').innerHTML=ICONS.map(e=>`<option value="${e.id}">${e.label_zh}</option>`).join('');
$('#icons').innerHTML=ICONS.map(e=>`<article class="card" data-category="${e.group}"><div class="art"><img src="${uri(e.svg)}" alt="${e.label_zh}"></div><h3>${e.label_zh}</h3><p>${e.description_zh}</p><div class="links"><button data-use="${e.id}">使用此图标</button><a href="${e.id}.svg" download>SVG ↓</a><a href="previews/${e.id}.png" download>PNG ↓</a></div></article>`).join('');
let selected=ICONS[0];function choose(id){selected=byId[id];$('#pick').value=id;$('#color').value=selected.primary_color;$('#width').value=120;$('#height').value=52;$('#name').value=selected.group==='proteins'?'Protein A':'';renderEditor()}
function renderEditor(){const e=selected,svg=new DOMParser().parseFromString(e.svg.replaceAll(e.primary_color,$('#color').value),'image/svg+xml').documentElement;svg.setAttribute('viewBox','0 0 160 192');svg.setAttribute('height','192');const editable=['generic-protein-rounded','generic-protein-capsule'].includes(e.id);$('#width').disabled=$('#height').disabled=!editable;$('#width').parentElement.hidden=$('#height').parentElement.hidden=!editable;let box=e.label_box;let anchors=structuredClone(e.anchors);if(editable){const w=+$('#width').value,h=+$('#height').value,r=svg.querySelector('rect');r.setAttribute('x',80-w/2);r.setAttribute('y',80-h/2);r.setAttribute('width',w);r.setAttribute('height',h);r.setAttribute('rx',e.id.endsWith('capsule')?h/2:Math.min(13,h/3));box=[80-w/2+8,80-h/2+5,w-16,h-10];anchors.top.point=[80,80-h/2];anchors.bottom.point=[80,80+h/2];anchors.left.point=[80-w/2,80];anchors.right.point=[80+w/2,80]}
 const name=$('#name').value.trim(),g=document.createElementNS(NS,'g');g.setAttribute('data-part','annotation');g.setAttribute('font-family','Arial, sans-serif');g.setAttribute('font-size','14');g.setAttribute('fill','#28474b');g.setAttribute('text-anchor','middle');const text=document.createElementNS(NS,'text');text.setAttribute('x',80);text.setAttribute('y',box?85:179);text.textContent=name;g.append(text);svg.append(g);$('#stage').replaceChildren(svg);if(text.getComputedTextLength()>(box?box[2]:140)){const split=Math.ceil(name.length/2);text.textContent='';[name.slice(0,split),name.slice(split)].forEach((s,i)=>{const t=document.createElementNS(NS,'tspan');t.setAttribute('x',80);t.setAttribute('y',i?94:77);t.textContent=s;text.append(t)});if(box&&[...text.children].some(t=>t.getComputedTextLength()>box[2]))[...text.children].forEach((t,i)=>t.setAttribute('y',i?187:170))}const metadata=document.createElementNS(NS,'metadata');metadata.textContent=JSON.stringify({source:e.id,anchors,label:name,primaryColor:$('#color').value});svg.prepend(metadata);$('#hint').textContent=e.description_zh}
$('#pick').onchange=()=>choose($('#pick').value);['name','color','width','height'].forEach(id=>$('#'+id).oninput=renderEditor);$('#reset').onclick=()=>choose(selected.id);document.querySelectorAll('[data-use]').forEach(b=>b.onclick=()=>{choose(b.dataset.use);$('#stage').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'center'})});$('#size').onchange=()=>document.querySelectorAll('.art img').forEach(im=>{im.style.width=$('#size').value+'px';im.style.height=$('#size').value+'px'});$('#category').onchange=()=>document.querySelectorAll('#icons .card').forEach(c=>c.hidden=$('#category').value!=='all'&&c.dataset.category!==$('#category').value);
$('#export').onclick=()=>{const xml=new XMLSerializer().serializeToString($('#stage svg')),url=URL.createObjectURL(new Blob([xml],{type:'image/svg+xml'})),a=document.createElement('a');a.href=url;a.download=selected.id+'-custom.svg';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
const cores=MODELS.map(m=>DomainMotion.make(m,ICONS));function renderPairs(t){cores.forEach((core,i)=>{const frame=core.frame(t);let out='';[65.6,155.2,244.8,334.4].forEach((x,k)=>{const raw=byId['generic-membrane'].svg.replace(/<svg[^>]*>/,'').replace(/<\\/svg>\\s*$/,'').replaceAll('generic-membrane',`pair${i}-membrane${k}`).replaceAll('stroke-width="1.6"',`stroke-width="${1.6/.7}"`);out+=`<g transform="translate(${x} 160) scale(.7) translate(-80 -80)">${raw}</g>`});for(const [id,p]of Object.entries(frame.poses)){const e=byId[core.entities[id].icon],raw=e.svg.replace(/<svg[^>]*>/,'').replace(/<\\/svg>\\s*$/,'').replaceAll(e.id,`pair${i}-${id}-${e.id}`).replaceAll('stroke-width="1.6"',`stroke-width="${1.6/p.s}"`);out+=`<g data-entity="${id}" transform="translate(${p.c}) rotate(${p.a*180/Math.PI}) scale(${p.s}) translate(-80 -80)">${raw}</g>`}$('#pair-'+i).innerHTML=out})}
let running=false,last=0;$('#progress').oninput=()=>{running=false;$('#play').textContent='播放';renderPairs(+$('#progress').value)};$('#play').onclick=()=>{running=!running;last=performance.now();if(running&&+$('#progress').value>=2)$('#progress').value=0;$('#play').textContent=running?'暂停':'播放';if(running)requestAnimationFrame(tick)};function tick(now){if(!running)return;$('#progress').value=Math.min(2,+$('#progress').value+(now-last)/1000);last=now;renderPairs(+$('#progress').value);if(+$('#progress').value>=2){running=false;$('#play').textContent='播放'}else requestAnimationFrame(tick)}choose(ICONS[0].id);renderPairs(2);
</script></body></html>'''
(f/'preview.html').write_text(page.replace('/*ENGINE*/',engine).replace('/*ICONS*/',json.dumps(icons,ensure_ascii=False)).replace('/*MODELS*/',json.dumps(models)))
print('Built generic picker, editor and two contact previews.')
